import { beforeEach, describe, expect, it } from "vitest";
import { selectItemCount, useCartStore } from "./cartStore";

describe("cart store", () => {
  beforeEach(() => {
    localStorage.clear();
    useCartStore.setState({ items: [], isOpen: false });
  });

  it("adds one more of an item already in the cart", () => {
    const { addItem } = useCartStore.getState();
    addItem("merino-base-layer");
    addItem("merino-base-layer");

    expect(useCartStore.getState().items).toEqual([{ slug: "merino-base-layer", quantity: 2 }]);
  });

  it("never goes past 10 of one item", () => {
    useCartStore.setState({ items: [{ slug: "titan-pot-set", quantity: 10 }] });
    useCartStore.getState().addItem("titan-pot-set");

    expect(useCartStore.getState().items).toEqual([{ slug: "titan-pot-set", quantity: 10 }]);
  });

  it("counts every item", () => {
    const { addItem } = useCartStore.getState();
    addItem("merino-base-layer");
    addItem("merino-base-layer");
    addItem("storm-shell-jacket");

    expect(selectItemCount(useCartStore.getState())).toBe(3);
  });

  it("saves the items, but not whether the drawer is open", () => {
    const { addItem, setOpen } = useCartStore.getState();
    addItem("storm-shell-jacket");
    setOpen(true);

    expect(JSON.parse(localStorage.getItem("trailhead-cart")!)).toEqual({
      state: { items: [{ slug: "storm-shell-jacket", quantity: 1 }] },
      version: 1,
    });
  });
});

import { render, screen } from "@testing-library/react";
import { MemoryRouter } from "react-router";
import { expect, it } from "vitest";
import type { ProductSummary } from "./schemas";
import { ProductCard } from "./ProductCard";

const tent: ProductSummary = {
  slug: "alpine-1p-tent",
  name: "Alpine 1P Tent",
  category: "tents",
  priceCents: 27900,
  imageUrl: "/images/products/alpine-1p-tent.webp",
  rating: { average: 4.7, count: 1 },
  inStock: false,
};

it("shows the name as a link to the product page", () => {
  render(<ProductCard product={tent} />, { wrapper: MemoryRouter });

  const link = screen.getByRole("link", { name: "Alpine 1P Tent" });
  expect(link).toHaveAttribute("href", "/products/alpine-1p-tent");
});

it("shows the price and an out of stock badge", () => {
  render(<ProductCard product={tent} />, { wrapper: MemoryRouter });

  expect(screen.getByText("$279.00")).toBeInTheDocument();
  expect(screen.getByText("Out of stock")).toBeInTheDocument();
});

it("has no badge when the product is in stock", () => {
  render(<ProductCard product={{ ...tent, inStock: true }} />, { wrapper: MemoryRouter });

  expect(screen.queryByText("Out of stock")).not.toBeInTheDocument();
});

import { render, screen } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { expect, it, vi } from "vitest";
import { AddToCartForm } from "./AddToCartForm";

it("sends the quantity the user typed", async () => {
  const user = userEvent.setup();
  const onAdd = vi.fn();
  render(<AddToCartForm productName="Storm Shell Jacket" onAdd={onAdd} />);

  const quantity = screen.getByLabelText("Quantity");
  await user.clear(quantity);
  await user.type(quantity, "3");
  expect(quantity).toHaveValue(3);

  await user.click(screen.getByRole("button", { name: "Add Storm Shell Jacket to cart" }));
  expect(onAdd).toHaveBeenCalledTimes(1);
  expect(onAdd).toHaveBeenCalledWith(3);
});

it("submits with the Enter key too", async () => {
  const user = userEvent.setup();
  const onAdd = vi.fn();
  render(<AddToCartForm productName="Storm Shell Jacket" onAdd={onAdd} />);

  await user.click(screen.getByLabelText("Quantity"));
  await user.keyboard("{Enter}");

  expect(onAdd).toHaveBeenCalledWith(1);
});

it("can't be pressed while disabled", async () => {
  const user = userEvent.setup();
  const onAdd = vi.fn();
  render(<AddToCartForm productName="Storm Shell Jacket" disabled onAdd={onAdd} />);

  const button = screen.getByRole("button", { name: /add storm shell/i });
  expect(button).toBeDisabled();
  await user.click(button);
  expect(onAdd).not.toHaveBeenCalled();
});

import { useState } from "react";

type AddToCartFormProps = {
  productName: string;
  disabled?: boolean;
  onAdd: (quantity: number) => void;
};

export function AddToCartForm({ productName, disabled = false, onAdd }: AddToCartFormProps) {
  const [quantity, setQuantity] = useState(1);

  return (
    <form
      onSubmit={(event) => {
        event.preventDefault();
        onAdd(quantity);
      }}
    >
      <label htmlFor="quantity">Quantity</label>
      <input
        id="quantity"
        type="number"
        min={1}
        max={10}
        required
        value={quantity}
        onChange={(event) => setQuantity(event.target.valueAsNumber || 1)}
      />
      <button type="submit" disabled={disabled}>
        Add {productName} to cart
      </button>
    </form>
  );
}

import { QueryClient, QueryClientProvider } from "@tanstack/react-query";
import { render } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import type { ReactElement } from "react";
import { createMemoryRouter, RouterProvider } from "react-router";
import { routes } from "@/app/routes";

export function createTestQueryClient() {
  return new QueryClient({
    defaultOptions: { queries: { retry: false, gcTime: Infinity }, mutations: { retry: false } },
  });
}

type Options = { path?: string; route?: string; queryClient?: QueryClient };

// Renders one component inside a fresh QueryClient and an in-memory router.
export function renderWithProviders(ui: ReactElement, options: Options = {}) {
  const { path = "/", route = path, queryClient = createTestQueryClient() } = options;
  const router = createMemoryRouter([{ path, element: ui }], { initialEntries: [route] });
  const user = userEvent.setup();
  const result = render(
    <QueryClientProvider client={queryClient}>
      <RouterProvider router={router} />
    </QueryClientProvider>,
  );
  return { ...result, user, queryClient, router };
}

// Renders the whole app, with its real routes, at one URL.
export function renderApp(route: string) {
  const queryClient = createTestQueryClient();
  const router = createMemoryRouter(routes, { initialEntries: [route] });
  const user = userEvent.setup();
  const result = render(
    <QueryClientProvider client={queryClient}>
      <RouterProvider router={router} />
    </QueryClientProvider>,
  );
  return { ...result, user, queryClient, router };
}

import { act, renderHook } from "@testing-library/react";
import { afterEach, beforeEach, expect, it, vi } from "vitest";
import { useDebouncedValue } from "./useDebouncedValue";

beforeEach(() => {
  vi.useFakeTimers();
});

afterEach(() => {
  vi.useRealTimers();
});

it("waits for the delay before changing", () => {
  const { result, rerender } = renderHook(({ value }) => useDebouncedValue(value, 300), {
    initialProps: { value: "ten" },
  });

  rerender({ value: "tent" });
  expect(result.current).toBe("ten");

  act(() => vi.advanceTimersByTime(299));
  expect(result.current).toBe("ten");

  act(() => vi.advanceTimersByTime(1));
  expect(result.current).toBe("tent");
});

import { afterEach, beforeEach, expect, it, vi } from "vitest";
import { postedAgo } from "./dates";

beforeEach(() => {
  vi.useFakeTimers();
  vi.setSystemTime(new Date("2026-10-01T09:00:00Z"));
});

afterEach(() => {
  vi.useRealTimers();
});

it("says yesterday for a day ago", () => {
  expect(postedAgo("2026-09-30T09:00:00Z")).toBe("yesterday");
});

it("counts the days for older dates", () => {
  expect(postedAgo("2026-09-24T09:00:00Z")).toBe("7 days ago");
});
